  ('owner-ubp-r02t-falcon-mecha-break-dark-night-den', 'MU-OWNER-UBP-R02T-FALCON-MECHA-BREAK-DARK-NIGHT-DEN', 'UBP-R02T - Falcon (Mecha BREAK, Dark Night / đen)', 'MOSHOW', 3444444, 3100000, 527000, 0),
  ('owner-moshow-toys-x-mecha-break-1-64-collector-s-box-falcon-custom', 'MU-OWNER-MOSHOW-TOYS-X-MECHA-BREAK-1-64-COLLECTOR-S-BOX-FALCON-CUSTOM', 'MOSHOW TOYS x MECHA BREAK 1/64 Collector''s Box : Falcon Custom', 'MOSHOW', 6111111, 5500000, 935000, 0)
) AS v(key, sku, name, brand, r, s, b, stock)
LEFT JOIN product_source ps ON ps."catalogKey" = v.key
WHERE p.id = ps."productId"
   OR (ps."productId" IS NULL AND (p.sku = v.sku OR p.name = v.name));

-- 3. Kiem tra doi soat tong quan
SELECT 
  count(*) AS "Tong_SP",
  count(*) FILTER (WHERE condition = 'preowned') AS "So_SP_2hand",
  count(*) FILTER (WHERE stock > 0) AS "So_SP_con_hang",
  count(*) FILTER (WHERE stock = 0) AS "So_SP_het_hang",
  sum(stock) AS "Tong_so_luong_ton"
FROM product 
WHERE "partnerId" IS NULL;

COMMIT;